"""`harness add` subcommand bodies.

Incremental customization after a minimal `harness init`. Lets users defer
stack / integration / governance choices and add them when needed.

Implements:
- `harness add stack <name>[:version]`
- `harness add integration <type> <provider>`
- `harness add governance <profile>`
"""

from __future__ import annotations

import re
import subprocess
import sys
from pathlib import Path
from typing import Any

from rich.console import Console
from ruamel.yaml import YAML

_console = Console()
_err = Console(stderr=True)


_FRAMEWORK_NAME_RE = re.compile(r"^[a-z][a-z0-9-]*$")
_STACK_ID_RE = re.compile(r"^[a-z][a-z0-9-]*$")


def _parse_stack_entry(entry: str) -> tuple[str | None, str | None]:
    """Parse `name:version` or `name`. Returns (framework, version_or_None).
    Returns (None, None) if framework name is malformed."""
    parts = entry.split(":", 1)
    framework = parts[0].strip().lower()
    version = parts[1].strip() if len(parts) == 2 and parts[1].strip() else None
    if not _FRAMEWORK_NAME_RE.fullmatch(framework):
        return None, None
    return framework, version


def _default_stack_id(framework: str, existing: list[dict[str, Any]]) -> str:
    """Generate a non-colliding stack id from the framework name."""
    base = framework
    used = {s.get("id") for s in existing}
    if base not in used:
        return base
    n = 2
    while f"{base}-{n}" in used:
        n += 1
    return f"{base}-{n}"


def cmd_add_stack(
    entry: str,
    *,
    stack_id: str | None = None,
    package_manager: str | None = None,
    test_runner: str | None = None,
    paths: str | None = None,
    config_path: Path = Path("harness.yaml"),
    regenerate: bool = True,
) -> int:
    """Append a stack to harness.yaml. Optionally re-run `harness generate`.

    Args:
        entry: `<framework>[:<version>]` (e.g. `nextjs:15`, `fastapi`)
        stack_id: defaults to framework name; auto-suffixed on collision
        package_manager: optional (pnpm, uv, cargo, ...)
        test_runner: optional (vitest, pytest, jest, ...)
        paths: comma-separated globs (default `**`)
        config_path: path to harness.yaml
        regenerate: run `harness generate` after the edit (default True)

    Returns: 0 success, 1 invalid input or missing config.
    """
    if not config_path.exists():
        _err.print(
            f"[red]{config_path} not found. Run `harness init` first.[/red]"
        )
        return 1

    framework, version = _parse_stack_entry(entry)
    if framework is None:
        _err.print(
            f"[red]Invalid stack entry {entry!r}. "
            "Use `<name>[:<version>]` with lowercase letters, digits, hyphens.[/red]"
        )
        return 1

    yaml = YAML()
    yaml.indent(mapping=2, sequence=4, offset=2)
    yaml.width = 120
    with config_path.open(encoding="utf-8") as f:
        cfg = yaml.load(f)

    if cfg is None:
        _err.print(f"[red]{config_path} is empty or malformed.[/red]")
        return 1

    stacks = cfg.get("stacks") or []

    # Resolve stack id
    resolved_id = stack_id or _default_stack_id(framework, stacks)
    if not _STACK_ID_RE.fullmatch(resolved_id):
        _err.print(
            f"[red]Invalid stack id {resolved_id!r}. "
            "Lowercase letters, digits, hyphens.[/red]"
        )
        return 1
    if any(s.get("id") == resolved_id for s in stacks):
        _err.print(
            f"[red]Stack id {resolved_id!r} already exists in {config_path}. "
            f"Pass --stack-id <other> to disambiguate.[/red]"
        )
        return 1

    # Compose new entry
    new_stack: dict[str, Any] = {"id": resolved_id, "framework": framework}
    if version:
        new_stack["version"] = version
    if package_manager:
        new_stack["package_manager"] = package_manager
    if test_runner:
        new_stack["test_runner"] = test_runner
    paths_list = (
        [p.strip() for p in paths.split(",") if p.strip()]
        if paths
        else ["**"]
    )
    new_stack["paths"] = paths_list

    stacks.append(new_stack)
    cfg["stacks"] = stacks

    with config_path.open("w", encoding="utf-8") as f:
        yaml.dump(cfg, f)

    _console.print(
        f"[green]added stack[/green] "
        f"[bold]{framework}{':' + version if version else ''}[/bold] "
        f"[dim](id={resolved_id}, pm={package_manager or '-'}, test={test_runner or '-'})[/dim]"
    )

    if regenerate:
        _console.print("[dim]running `harness generate`…[/dim]")
        result = subprocess.run(
            [sys.executable, "-m", "harness", "generate"],
            capture_output=True, text=True,
        )
        if result.returncode != 0:
            _err.print(
                f"[red]harness generate failed:[/red]\n{result.stdout}\n{result.stderr}"
            )
            return result.returncode
        # Echo the final line of generate's stdout for confirmation
        lines = [line for line in result.stdout.strip().splitlines() if line]
        if lines:
            _console.print(f"[dim]{lines[-1]}[/dim]")
    else:
        _console.print(
            "[dim]Skipped regenerate. Run `harness generate` to materialise the change.[/dim]"
        )

    return 0


# Allowed enum values mirror src/harness/config/models.py.
_INTEGRATION_PROVIDERS: dict[str, set[str]] = {
    "issue-tracker": {"jira", "linear", "github", "azure-devops", "none"},
    "doc-tracker":   {"local", "confluence", "notion"},
    "design":        {"figma", "stitch", "claude-design", "html-mockup", "none"},
}
_INTEGRATION_YAML_KEY: dict[str, str] = {
    "issue-tracker": "issue_tracker",
    "doc-tracker":   "doc_tracker",
    "design":        "design",
}
_GOVERNANCE_PROFILES = {"standard", "strict", "hipaa", "pci", "sox", "gdpr"}

# ---- domain helpers ----------------------------------------------------------

# Maps family keywords to a bundled domain slug whose profile is used as suggestions.
_FAMILY_MAP: dict[str, str] = {
    "health": "healthcare", "medical": "healthcare", "patient": "healthcare",
    "clinical": "healthcare", "pharma": "healthcare", "pharmaceutical": "healthcare",
    "drug": "healthcare", "hospital": "healthcare", "ehr": "healthcare", "emr": "healthcare",
    "hipaa": "healthcare",
    "bank": "fintech", "banking": "fintech", "lending": "fintech", "payment": "fintech",
    "financial": "fintech", "crypto": "fintech", "fintech": "fintech", "invest": "fintech",
    "wallet": "fintech", "kyc": "fintech", "aml": "fintech",
    "dod": "defense", "military": "defense", "defense": "defense", "cmmc": "defense",
    "fedramp": "defense", "itar": "defense", "classified": "defense",
    "retail": "retail", "ecommerce": "retail", "shop": "retail", "commerce": "retail",
    "marketplace": "retail",
    "education": "edtech", "edtech": "edtech", "school": "edtech", "student": "edtech",
    "learning": "edtech", "lms": "edtech", "university": "edtech",
    "saas": "saas", "platform": "saas", "subscription": "saas", "b2b": "saas",
    "government": "govtech", "gov": "govtech", "federal": "govtech", "citizen": "govtech",
    "legal": "legaltech", "law": "legaltech", "lawyer": "legaltech", "attorney": "legaltech",
    "contract": "legaltech",
    "insurance": "insurance", "insure": "insurance", "actuarial": "insurance", "claim": "insurance",
}


def _load_bundled_domains() -> list[dict[str, Any]]:
    """Return the bundled domain profiles list."""
    import json as _json
    from pathlib import Path as _Path
    template_path = (
        _Path(__file__).parent.parent / "templates" / "base" / "config" / "domains.json"
    )
    if not template_path.exists():
        return []
    result: list[dict[str, Any]] = _json.loads(template_path.read_text(encoding="utf-8"))
    return result


def _family_seeds(slug: str) -> dict[str, Any]:
    """Return the bundled profile dict for the best-matching domain family, or {}."""
    slug_lower = slug.lower()
    for keyword, family in _FAMILY_MAP.items():
        if keyword in slug_lower:
            profiles = _load_bundled_domains()
            for p in profiles:
                if p["domain"] == family:
                    return p
    return {}


def _checkbox_step(
    prompt: str,
    suggestions: list[str],
    example: str = "",
) -> list[str]:
    """Two-prompt step: checkbox of pre-checked suggestions + free-text additions.

    Returns combined list. Loops until user confirms."""
    import questionary

    while True:
        if suggestions:
            choices = [questionary.Choice(s, checked=True) for s in suggestions]
            selected: list[str] = questionary.checkbox(prompt, choices=choices).unsafe_ask() or []
        else:
            selected = []

        hint = f" (comma-separated{', e.g.: ' + example if example else ''})"
        extra_raw: str = questionary.text(
            f"Add more{hint}, or leave blank:"
        ).unsafe_ask() or ""
        extra = [item.strip() for item in extra_raw.split(",") if item.strip()]

        combined = selected + [e for e in extra if e not in selected]

        if combined:
            _console.print(f"  [dim]Collected:[/dim] {', '.join(combined)}")
        else:
            _console.print("  [dim](none)[/dim]")

        ok = questionary.confirm("Looks good?", default=True).unsafe_ask()
        if ok:
            return combined


def cmd_list_domains() -> int:
    """Print the bundled domain library (slug + first key_concern)."""
    profiles = _load_bundled_domains()
    if not profiles:
        _err.print("[red]No bundled domain profiles found.[/red]")
        return 1
    _console.print("\n[bold]Available domains:[/bold]")
    for p in profiles:
        first_concern = p.get("key_concerns", [""])[0] or ""
        _console.print(f"  [bold]{p['domain']:14}[/bold] — {first_concern}")
    _console.print(
        "\n[dim]Run `harness add domain <name>` to add one to your project.[/dim]\n"
    )
    return 0


def cmd_add_domain(
    name: str,
    *,
    config_path: Path = Path("harness.yaml"),
    regenerate: bool = True,
) -> int:
    """Add a domain to this project. Runs a suggest-and-confirm wizard for custom domains.

    Args:
        name: domain slug (known library slug or custom name)
        config_path: path to harness.yaml
        regenerate: run `harness generate` after edit (default True)

    Returns: 0 success, 1 error / abort.
    """
    import questionary

    if not config_path.exists():
        _err.print(f"[red]{config_path} not found. Run `harness init` first.[/red]")
        return 1

    bundled = _load_bundled_domains()
    known_slugs = {p["domain"] for p in bundled}

    yaml = YAML()
    yaml.indent(mapping=2, sequence=4, offset=2)
    yaml.width = 120
    with config_path.open(encoding="utf-8") as f:
        cfg = yaml.load(f)
    if cfg is None:
        _err.print(f"[red]{config_path} is empty or malformed.[/red]")
        return 1

    domains_cfg: dict[str, Any] = cfg.get("domains") or {}
    selected: list[str] = list(domains_cfg.get("selected") or [])
    custom_profiles: dict[str, Any] = dict(domains_cfg.get("custom_profiles") or {})

    if name in known_slugs:
        # Known library domain — just add to selected
        if name in selected:
            _console.print(f"[dim]Domain '{name}' is already in selected — nothing to do.[/dim]")
            return 0
        selected.append(name)
        domains_cfg["selected"] = selected
        cfg["domains"] = domains_cfg
        with config_path.open("w", encoding="utf-8") as f:
            yaml.dump(cfg, f)
        _console.print(f"[green]added domain[/green] [bold]{name}[/bold]")
    else:
        # Custom domain — 5-step suggest-and-confirm wizard
        _console.print(
            f"\n[yellow]⚠[/yellow]  [bold]{name!r}[/bold] is not in the built-in library.\n"
            "   I'll walk you through creating a complete domain profile.\n"
            "   Suggestions are based on similar domains — confirm, uncheck, or add more.\n"
        )

        # Check if already exists as custom profile
        if name in custom_profiles:
            overwrite = questionary.confirm(
                f"'{name}' is already configured as a custom domain. Update the existing profile?",
                default=False,
            ).unsafe_ask()
            if not overwrite:
                _console.print("[dim]Aborted.[/dim]")
                return 0

        seeds = _family_seeds(name)

        _console.rule("Step 1/5 — Signals (keywords that trigger domain detection in /arh-generate-prd)")
        _console.print("[dim]These keywords are matched against the product description.[/dim]")
        signals = _checkbox_step(
            "Select signals (pre-checked = suggestions):",
            suggestions=seeds.get("signals", []),
            example="FDA, GxP, 21 CFR, pharma",
        )

        _console.rule("Step 2/5 — Key regulatory concerns")
        _console.print("[dim]Used to generate domain-specific questions in Rounds 3 & 4.[/dim]")
        key_concerns = _checkbox_step(
            "Select key concerns:",
            suggestions=seeds.get("key_concerns", []),
            example="FDA 21 CFR Part 11, GxP compliance",
        )

        _console.rule("Step 3/5 — Required knowledge")
        _console.print("[dim]Specific regulations and standards the team must know.[/dim]")
        required_knowledge = _checkbox_step(
            "Select required knowledge items:",
            suggestions=seeds.get("required_knowledge", []),
            example="FDA 21 CFR Part 11 — electronic records",
        )

        _console.rule("Step 4/5 — Web searches (for domain-research-agent)")
        _console.print("[dim]Use {date} as a placeholder for the current year.[/dim]")
        web_searches = _checkbox_step(
            "Select web search queries:",
            suggestions=seeds.get("web_searches", []),
            example="FDA 21 CFR Part 11 compliance requirements {date}",
        )

        _console.rule("Step 5/5 — Special PRD sections")
        _console.print("[dim]Sections appended to the PRD for this domain.[/dim]")
        special_sections = _checkbox_step(
            "Select special PRD sections:",
            suggestions=seeds.get("special_sections", []),
            example="FDA 21 CFR Part 11 Compliance Plan",
        )

        # Summary
        _console.rule()
        _console.print(f"[bold]Profile summary for '{name}':[/bold]")
        _console.print(f"  Signals:       {len(signals)}")
        _console.print(f"  Key concerns:  {len(key_concerns)}")
        _console.print(f"  Knowledge:     {len(required_knowledge)}")
        _console.print(f"  Web searches:  {len(web_searches)}")
        _console.print(f"  PRD sections:  {len(special_sections)}")
        _console.print("  Complexity:    medium")

        save = questionary.confirm("Save this domain?", default=True).unsafe_ask()
        if not save:
            _console.print("[dim]Aborted. Nothing written.[/dim]")
            return 0

        # Persist custom profile in harness.yaml
        profile_dict: dict[str, Any] = {
            "signals": signals,
            "complexity": "medium",
            "key_concerns": key_concerns,
            "required_knowledge": required_knowledge,
            "suggested_workflow": "domain-research",
            "web_searches": web_searches,
            "special_sections": special_sections,
        }
        custom_profiles[name] = profile_dict
        if name not in selected:
            selected.append(name)

        domains_cfg["selected"] = selected
        domains_cfg["custom_profiles"] = custom_profiles
        cfg["domains"] = domains_cfg

        with config_path.open("w", encoding="utf-8") as f:
            yaml.dump(cfg, f)

        _console.print(
            f"\n[green]✓[/green] Domain [bold]{name!r}[/bold] saved to {config_path}.\n"
            f"[dim]Run /arh-generate-prd to use domain-specific detection and research.[/dim]"
        )

    if regenerate:
        return _regenerate(f"add domain {name}")
    _console.print("[dim]Skipped regenerate. Run `harness generate` to materialise the change.[/dim]")
    return 0


def _regenerate(label: str) -> int:
    """Run `harness generate` and echo the last summary line. Returns rc."""
    _console.print("[dim]running `harness generate`…[/dim]")
    result = subprocess.run(
        [sys.executable, "-m", "harness", "generate"],
        capture_output=True, text=True,
    )
    if result.returncode != 0:
        _err.print(
            f"[red]harness generate failed after {label}:[/red]\n"
            f"{result.stdout}\n{result.stderr}"
        )
        return result.returncode
    lines = [line for line in result.stdout.strip().splitlines() if line]
    if lines:
        _console.print(f"[dim]{lines[-1]}[/dim]")
    return 0


def cmd_add_integration(
    integration_type: str,
    provider: str,
    *,
    config_path: Path = Path("harness.yaml"),
    regenerate: bool = True,
) -> int:
    """Flip an integration provider in harness.yaml. Optionally regenerate.

    Args:
        integration_type: `issue-tracker | doc-tracker | design`
        provider: enum member matching the type (e.g. `jira` for issue-tracker)
        config_path: path to harness.yaml
        regenerate: run `harness generate` after edit (default True)

    Returns: 0 success, 1 invalid input or missing config.

    Note: tracker MCP discovery (Atlassian site + Jira project resolution,
    Linear team selection, etc.) happens at `/arh-intake` Step 0 the next time
    the user runs intake. This command only flips the literal — the wizard
    self-heals placeholder configs.
    """
    if integration_type not in _INTEGRATION_PROVIDERS:
        _err.print(
            f"[red]Unknown integration type {integration_type!r}. "
            f"Valid: {sorted(_INTEGRATION_PROVIDERS)}.[/red]"
        )
        return 1

    valid_providers = _INTEGRATION_PROVIDERS[integration_type]
    if provider not in valid_providers:
        _err.print(
            f"[red]Unknown provider {provider!r} for {integration_type}. "
            f"Valid: {sorted(valid_providers)}.[/red]"
        )
        return 1

    if not config_path.exists():
        _err.print(
            f"[red]{config_path} not found. Run `harness init` first.[/red]"
        )
        return 1

    yaml = YAML()
    yaml.indent(mapping=2, sequence=4, offset=2)
    yaml.width = 120
    with config_path.open(encoding="utf-8") as f:
        cfg = yaml.load(f)
    if cfg is None:
        _err.print(f"[red]{config_path} is empty or malformed.[/red]")
        return 1

    integrations = cfg.get("integrations") or {}
    yaml_key = _INTEGRATION_YAML_KEY[integration_type]
    prev = integrations.get(yaml_key, "none")
    integrations[yaml_key] = provider
    cfg["integrations"] = integrations

    with config_path.open("w", encoding="utf-8") as f:
        yaml.dump(cfg, f)

    _console.print(
        f"[green]set integrations.{yaml_key}[/green] "
        f"[dim]{prev}[/dim] → [bold]{provider}[/bold]"
    )

    if provider != "none" and provider not in {"local", "html-mockup", "claude-design"}:
        _console.print(
            f"[dim]Next: `/arh-intake` Step 0 will discover {provider} via MCP and "
            f"populate `docs/config/{yaml_key.replace('_', '-')}.yaml` on first run. "
            f"Ensure the matching MCP server is configured.[/dim]"
        )

    if regenerate:
        return _regenerate(f"add integration {integration_type}={provider}")
    _console.print(
        "[dim]Skipped regenerate. Run `harness generate` to materialise the change.[/dim]"
    )
    return 0


def cmd_add_governance(
    profile: str,
    *,
    config_path: Path = Path("harness.yaml"),
    regenerate: bool = True,
) -> int:
    """Switch governance.profile in harness.yaml. Optionally regenerate.

    Args:
        profile: `standard | strict | hipaa | pci | sox | gdpr`
        config_path: path to harness.yaml
        regenerate: run `harness generate` after edit (default True)

    Returns: 0 success, 1 invalid input or missing config.

    Note: compliance overlays (hipaa, pci, sox, gdpr) ship as scaffolds —
    rule bodies are TODO slots the team authors per regulation. F-013
    surfaces the unfilled slot count after regenerate.
    """
    if profile not in _GOVERNANCE_PROFILES:
        _err.print(
            f"[red]Unknown governance profile {profile!r}. "
            f"Valid: {sorted(_GOVERNANCE_PROFILES)}.[/red]"
        )
        return 1

    if not config_path.exists():
        _err.print(
            f"[red]{config_path} not found. Run `harness init` first.[/red]"
        )
        return 1

    yaml = YAML()
    yaml.indent(mapping=2, sequence=4, offset=2)
    yaml.width = 120
    with config_path.open(encoding="utf-8") as f:
        cfg = yaml.load(f)
    if cfg is None:
        _err.print(f"[red]{config_path} is empty or malformed.[/red]")
        return 1

    governance = cfg.get("governance") or {}
    prev = governance.get("profile", "standard")
    governance["profile"] = profile
    cfg["governance"] = governance

    with config_path.open("w", encoding="utf-8") as f:
        yaml.dump(cfg, f)

    _console.print(
        f"[green]set governance.profile[/green] "
        f"[dim]{prev}[/dim] → [bold]{profile}[/bold]"
    )

    if profile in {"hipaa", "pci", "sox", "gdpr"}:
        _console.print(
            f"[dim]Compliance overlay ships as scaffold. "
            f"Rule bodies under `.claude/rules/{profile}/` are TODO slots; "
            f"team authors content per regulation. `harness list todos` shows progress.[/dim]"
        )

    if regenerate:
        return _regenerate(f"add governance {profile}")
    _console.print(
        "[dim]Skipped regenerate. Run `harness generate` to materialise the change.[/dim]"
    )
    return 0
